import sys

def count_pairs(s, x):
    # Check basic feasibility
    if s < x or (s - x) % 2 != 0:
        return 0

    a = (s - x) // 2

    # a and x must not share any '1' bits
    if a & x:
        return 0

    # Count number of bits set in x
    cnt = bin(x).count('1')

    # Total combinations: 2^cnt
    res = 1 << cnt

    # Exclude the case where a == 0 (since a and b must be positive)
    # This happens when a == 0 and b == x, which corresponds to one combination
    if a == 0:
        res -= 2

    return max(res, 0)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    s, x = map(int, data)
    print(count_pairs(s, x))

if __name__ == "__main__":
    main()
